"use client";

import { useState } from "react";
import { ArrowsLeftRight, Plus, X } from "@phosphor-icons/react";
import type { Participante } from "@/components/ParticipantForm";
import type { Exclusion } from "@/lib/sorteo";

interface Props {
  participantes: Participante[];
  exclusiones: Exclusion[];
  /** Devuelve el mensaje de error, o null si la exclusión se agregó. */
  alAgregar: (correo1: string, correo2: string) => string | null;
  alEliminar: (indice: number) => void;
}

/** Nombre visible de un participante por su correo (sin mayúsculas/minúsculas). */
function nombreDe(participantes: Participante[], correo: string): string {
  return (
    participantes.find(
      (p) => p.correo.toLowerCase() === correo.toLowerCase(),
    )?.nombre ?? correo
  );
}

/**
 * Sección para registrar pares de participantes que no pueden recibirse como
 * asignación (la exclusión funciona en ambas direcciones).
 */
export default function Exclusiones({
  participantes,
  exclusiones,
  alAgregar,
  alEliminar,
}: Props) {
  const [correo1, setCorreo1] = useState("");
  const [correo2, setCorreo2] = useState("");
  const [error, setError] = useState<string | null>(null);

  if (participantes.length < 2) {
    return (
      <p className="text-sm text-tinta-suave">
        Agrega al menos 2 participantes para poder definir exclusiones.
      </p>
    );
  }

  function manejarAgregado(e: React.FormEvent) {
    e.preventDefault();
    if (!correo1 || !correo2) {
      setError("Selecciona a ambas personas del par excluido.");
      return;
    }
    const problema = alAgregar(correo1, correo2);
    if (problema) {
      setError(problema);
      return;
    }
    setCorreo1("");
    setCorreo2("");
    setError(null);
  }

  return (
    <div className="space-y-4">
      <form onSubmit={manejarAgregado} className="space-y-2" noValidate>
        <div className="flex flex-wrap items-center gap-2">
          <select
            aria-label="Primer participante del par excluido"
            value={correo1}
            onChange={(e) => {
              setCorreo1(e.target.value);
              setError(null);
            }}
            className="campo w-auto min-w-36 flex-1"
          >
            <option value="">Elegir…</option>
            {participantes.map((p) => (
              <option key={p.correo} value={p.correo}>
                {p.nombre}
              </option>
            ))}
          </select>
          <ArrowsLeftRight
            aria-hidden="true"
            weight="bold"
            className="size-4 shrink-0 text-tinta-suave"
          />
          <select
            aria-label="Segundo participante del par excluido"
            value={correo2}
            onChange={(e) => {
              setCorreo2(e.target.value);
              setError(null);
            }}
            className="campo w-auto min-w-36 flex-1"
          >
            <option value="">Elegir…</option>
            {participantes.map((p) => (
              <option key={p.correo} value={p.correo}>
                {p.nombre}
              </option>
            ))}
          </select>
          <button type="submit" className="boton-accion">
            <Plus aria-hidden="true" weight="bold" className="size-4" />
            Añadir exclusión
          </button>
        </div>
        <p aria-live="polite" className="min-h-5 text-sm text-regalo">
          {error}
        </p>
      </form>

      {exclusiones.length > 0 ? (
        <ul className="space-y-2">
          {exclusiones.map((excluida, indice) => {
            const primero = nombreDe(participantes, excluida.correo1);
            const segundo = nombreDe(participantes, excluida.correo2);
            return (
              <li
                key={`${excluida.correo1}|${excluida.correo2}`}
                aria-label={`${primero} ↔ ${segundo}`}
                className="flex items-center justify-between gap-2 rounded-xl bg-oro-suave/60 px-3 py-2 text-sm"
              >
                <span className="flex min-w-0 items-center gap-2">
                  <span className="truncate font-semibold">{primero}</span>
                  <ArrowsLeftRight
                    aria-hidden="true"
                    weight="bold"
                    className="size-3.5 shrink-0 text-oro"
                  />
                  <span className="truncate font-semibold">{segundo}</span>
                </span>
                <button
                  type="button"
                  onClick={() => alEliminar(indice)}
                  className="inline-flex min-h-11 items-center gap-1 rounded-lg px-2.5 py-1.5 text-xs font-semibold text-regalo transition hover:bg-regalo-suave focus-visible:ring-2 focus-visible:ring-regalo focus-visible:outline-none"
                  aria-label={`Eliminar la exclusión entre ${primero} y ${segundo}`}
                >
                  <X aria-hidden="true" weight="bold" className="size-3.5" />
                  Quitar
                </button>
              </li>
            );
          })}
        </ul>
      ) : (
        <p className="text-sm text-tinta-suave">
          Sin exclusiones: cualquier persona puede recibir a cualquiera.
        </p>
      )}
    </div>
  );
}

"use client";

/** Tipo de sorteo: "individual" (clásico) o "multiple" (varios amigos secretos). */
export type TipoSorteo = "individual" | "multiple";

/** Estado de la configuración editable por el organizador. */
export interface EstadoConfig {
  tipo: TipoSorteo;
  /** Cantidad de amigos secretos por participante (solo si tipo es múltiple). */
  cantidadAmigos: number;
  /** Textos crudos de los campos de monto; "" significa sin definir. */
  montoMinimo: string;
  montoMaximo: string;
}

export const CONFIG_INICIAL: EstadoConfig = {
  tipo: "individual",
  cantidadAmigos: 2,
  montoMinimo: "",
  montoMaximo: "",
};

interface Props {
  config: EstadoConfig;
  numParticipantes: number;
  alActualizar: (actualizacion: Partial<EstadoConfig>) => void;
}

/** Numero positivo o NaN/negativo si el texto no es un monto válido. */
function aNumero(crudo: string): number {
  if (crudo.trim() === "") return NaN;
  const valor = Number(crudo);
  return Number.isFinite(valor) ? valor : NaN;
}

/** Indica si el texto es vacío o un monto positivo válido. */
function montoValido(crudo: string): boolean {
  return crudo.trim() === "" || aNumero(crudo) > 0;
}

/**
 * La configuración permite sortear: participantes suficientes, cantidad de
 * amigos secretos en rango y montos numéricamente coherentes.
 */
export function esConfiguracionValida(
  config: EstadoConfig,
  numParticipantes: number,
): boolean {
  if (numParticipantes < 2) return false;
  if (config.tipo === "multiple") {
    const maxima = numParticipantes - 1;
    if (
      !Number.isInteger(config.cantidadAmigos) ||
      config.cantidadAmigos < 2 ||
      config.cantidadAmigos > maxima
    ) {
      return false;
    }
  }
  if (!montoValido(config.montoMinimo) || !montoValido(config.montoMaximo)) {
    return false;
  }
  const minimo = aNumero(config.montoMinimo);
  const maximo = aNumero(config.montoMaximo);
  if (Number.isFinite(minimo) && Number.isFinite(maximo) && minimo > maximo) {
    return false;
  }
  return true;
}

/** Tarjeta de opción de radio: resaltada cuando está marcada. */
function OpcionRadio({
  nombre,
  valor,
  marcada,
  alElegir,
  texto,
}: {
  nombre: string;
  valor: string;
  marcada: boolean;
  alElegir: () => void;
  texto: string;
}) {
  return (
    <label
      className={`flex cursor-pointer items-start gap-2.5 rounded-xl border px-3.5 py-3 text-sm transition has-checked:border-regalo has-checked:bg-regalo-suave/50 has-checked:shadow-sm ${
        marcada ? "border-regalo bg-regalo-suave/50" : "border-caramelo"
      } hover:border-regalo/50`}
    >
      <input
        type="radio"
        name={nombre}
        value={valor}
        checked={marcada}
        onChange={alElegir}
        className="mt-0.5 size-4 shrink-0 accent-[var(--color-regalo)]"
      />
      <span>{texto}</span>
    </label>
  );
}

/** Sección de configuración: tipo de sorteo, cantidad y monto sugerido. */
export default function ConfiguracionSorteo({
  config,
  numParticipantes,
  alActualizar,
}: Props) {
  const esMultiple = config.tipo === "multiple";
  const maximaCantidad = numParticipantes - 1;
  const cantidadInvalida =
    esMultiple &&
    (config.cantidadAmigos < 2 || config.cantidadAmigos > maximaCantidad);

  return (
    <div className="space-y-5">
      <fieldset>
        <legend className="mb-2 text-sm font-semibold text-tinta">
          Tipo de sorteo
        </legend>
        <div className="flex flex-col gap-2">
          <OpcionRadio
            nombre="tipo-sorteo"
            valor="individual"
            marcada={config.tipo === "individual"}
            alElegir={() => alActualizar({ tipo: "individual" })}
            texto="Individual (clásico): una persona, un regalo"
          />
          <OpcionRadio
            nombre="tipo-sorteo"
            valor="multiple"
            marcada={config.tipo === "multiple"}
            alElegir={() => alActualizar({ tipo: "multiple" })}
            texto="Multiple: cada quien regala a varias personas"
          />
        </div>
      </fieldset>

      {esMultiple && (
        <div>
          <label
            htmlFor="cantidad-amigos"
            className="mb-1 block text-sm font-semibold text-tinta"
          >
            Cantidad de amigos secretos por participante
          </label>
          <input
            id="cantidad-amigos"
            type="number"
            min={2}
            max={maximaCantidad > 1 ? maximaCantidad : 2}
            value={config.cantidadAmigos}
            onChange={(e) =>
              alActualizar({ cantidadAmigos: Number(e.target.value) })
            }
            className="campo w-40"
          />
          {cantidadInvalida && (
            <p aria-live="polite" className="mt-1 text-sm text-regalo">
              La cantidad debe estar entre 2 y la cantidad de participantes
              menos uno (hoy: {Math.max(maximaCantidad, 2)}).
            </p>
          )}
        </div>
      )}

      <fieldset>
        <legend className="text-sm font-semibold text-tinta">
          Monto sugerido del regalo (opcional)
        </legend>
        <p className="mt-1 text-xs text-tinta-suave">
          Puedes definir solo un mínimo, o un mínimo y un máximo como rango.
        </p>
        <div className="mt-2 flex flex-wrap items-end gap-3">
          <label className="flex flex-col gap-1 text-xs font-medium text-tinta-suave">
            Mínimo
            <input
              type="number"
              min={0}
              step="0.01"
              aria-label="Monto mínimo sugerido"
              value={config.montoMinimo}
              onChange={(e) => alActualizar({ montoMinimo: e.target.value })}
              className="campo w-32"
            />
          </label>
          <label className="flex flex-col gap-1 text-xs font-medium text-tinta-suave">
            Máximo
            <input
              type="number"
              min={0}
              step="0.01"
              aria-label="Monto máximo sugerido"
              value={config.montoMaximo}
              onChange={(e) => alActualizar({ montoMaximo: e.target.value })}
              className="campo w-32"
            />
          </label>
        </div>
        {(!montoValido(config.montoMinimo) || !montoValido(config.montoMaximo)) && (
          <p aria-live="polite" className="mt-1 text-sm text-regalo">
            Los montos deben ser números mayores que cero.
          </p>
        )}
        {!cantidadInvalida &&
          montoValido(config.montoMinimo) &&
          montoValido(config.montoMaximo) &&
          aNumero(config.montoMinimo) > aNumero(config.montoMaximo) &&
          config.montoMinimo.trim() !== "" &&
          config.montoMaximo.trim() !== "" && (
            <p aria-live="polite" className="mt-1 text-sm text-regalo">
              El monto máximo no puede ser menor que el mínimo.
            </p>
          )}
      </fieldset>
    </div>
  );
}

